// React roadmap questions — set A (100): "what renders / what does this hook do
// / what is the value". 25 levels × 4. Combined with set B
// (lib/roadmap-questions.ts) this gives 8 per level. See lib/roadmap.ts.

import type { Seed } from './roadmap-build';

export const reactSeedsA: Seed[] = [
  // ── Level 1 — JSX Basics ───────────────────────────────────────────────
  { q: 'What does App render?\n\n```jsx\nfunction App() {\n  return <h1>Hello</h1>;\n}\n```', opts: ['An h1 with text "Hello"', 'The string "Hello"', 'Nothing', 'An error'], a: 0, e: 'JSX is syntax for describing elements; <h1>Hello</h1> becomes an h1 DOM element whose text content is Hello. It is not a string, so no quotes appear and nothing is parsed at runtime, and a component that returns valid JSX renders without error.', intro: 'JSX is not a string: think about what the browser ends up with when React renders a tag written this way.', tags: ['JSX'] },
  { q: 'What does the paragraph show?\n\n```jsx\nconst x = 5;\n<p>{x + 1}</p>;\n```', opts: ['6', '5', 'x + 1', '{x + 1}'], a: 0, e: 'Inside JSX, curly braces embed a JavaScript expression and React renders its value, so x + 1 is evaluated to 6. The text x + 1 would appear only if it were written outside braces as literal content, and the braces themselves are never rendered; 5 would ignore the addition.', intro: 'Curly braces switch from markup back to JavaScript. Ask what JavaScript does with x + 1 before React puts anything on the page.', tags: ['JSX', 'Expressions'] },
  { q: 'What is rendered?\n\n```jsx\n<div>{2 + 2}</div>;\n```', opts: ['"2 + 2"', '4', '{4}', 'an error'], a: 1, e: 'The expression inside braces is evaluated, so the div shows 4.', tags: ['JSX', 'Expressions'] },
  { q: 'What is rendered?\n\n```jsx\nconst name = "Sam";\n<p>Hi {name}</p>;\n```', opts: ['"Hi {name}"', 'Hi Sam', 'Hi name', 'an error'], a: 1, e: 'Text outside braces is rendered literally, while {name} is a JavaScript expression that React replaces with its value, so the paragraph reads Hi Sam. Hi name would require the identifier to be plain text, and the braces and quotes are never shown, because JSX children are elements and text, not a string.', intro: 'Part of this content is plain text and part is inside braces. Only one of those parts is treated as JavaScript.', tags: ['JSX'] },

  // ── Level 2 — Components ────────────────────────────────────────────────
  { q: 'What does App render?\n\n```jsx\nfunction Welcome() {\n  return <p>Welcome</p>;\n}\nfunction App() {\n  return <Welcome />;\n}\n```', opts: ['<p>Welcome</p>', 'The string "Welcome"', 'Nothing', 'An error'], a: 0, e: '<Welcome /> tells React to call the Welcome component and render whatever it returns, so App ends up rendering <p>Welcome</p>. React never inserts the component\'s name as a string, and nesting components this way is the normal way to compose a UI, not an error.', intro: 'App does not return the text Welcome itself; follow what React does when it meets a capitalised tag.', tags: ['Components'] },
  { q: 'Why might <app /> not work as a component?\n\n```jsx\nfunction app() {\n  return <div />;\n}\n```', opts: ['Components must start uppercase', 'It is missing a return', 'It needs props', 'Syntax error'], a: 0, e: 'JSX compiles lowercase tags to DOM elements (createElement(\'app\')) and capitalised tags to component references, so <app /> creates an unknown HTML element and the app function is never called; React warns that the tag is unrecognised. The code is valid syntax and has a return, so renaming the component to App is the fix.', intro: 'React has to tell HTML tags like div apart from components. Think about the rule it uses to do that.', tags: ['Components', 'JSX'] },
  { q: 'What does wrapping the two paragraphs in <>...</> do?\n\n```jsx\nfunction App() {\n  return (\n    <>\n      <p>A</p>\n      <p>B</p>\n    </>\n  );\n}\n```', opts: ['Groups them without adding an element to the DOM', 'Wraps them in a div element', 'Turns them into an array that needs keys', 'Nothing; a component may return two elements side by side'], a: 0, e: '<>...</> is a Fragment: it lets a component return several children as one node without adding an element to the DOM, so only the two p elements appear. A div would add a real element that can break layout or CSS, and two adjacent elements with no wrapper are a JSX syntax error. Fragments need keys only when produced from a list, using the explicit <Fragment key={...}> form.', intro: 'A component returns one root node. Ask what this root node becomes in the browser\'s DOM.', tags: ['Components', 'Fragment'] },
  { q: 'What is rendered?\n\n```jsx\nfunction Sum() {\n  return <p>{1 + 2 + 3}</p>;\n}\n```', opts: ['"1 + 2 + 3"', '6', '"123"', 'an error'], a: 1, e: 'The arithmetic expression evaluates to 6.', tags: ['Components', 'Expressions'] },

  // ── Level 3 — Props ────────────────────────────────────────────────────
  { q: 'What is rendered?\n\n```jsx\nfunction Hello({ name }) {\n  return <p>Hi {name}</p>;\n}\n<Hello name="Ada" />;\n```', opts: ['"Hi name"', 'Hi Ada', '"Hi {name}"', 'an error'], a: 1, e: 'The attribute name="Ada" is passed to Hello as props.name; destructuring { name } in the parameter list reads it, and {name} renders its value, giving Hi Ada. Hi name would appear only if name were plain text rather than an expression, and the braces are never rendered.', intro: 'The attribute on <Hello> becomes a field on the props object, which the parameter list destructures. Follow that value into the JSX.', tags: ['Props'] },
  { q: 'What inline style does the div end up with?\n\n```jsx\nfunction Box({ width }) {\n  return <div style={{ width }} />;\n}\n<Box width={100} />;\n```', opts: ['width: 100px', 'width: 100', 'width: "width"', 'no style attribute'], a: 0, e: 'style={{ width }} is shorthand for style={{ width: width }}, so the div receives width: 100; React appends px to unitless numbers for most CSS properties, so the rendered attribute is style="width:100px". The browser would ignore width: 100 without a unit, which is why React adds it, and the prop name width is never used as the value.', intro: 'The style prop takes an object, and width here is a number. Recall how React turns a numeric CSS value into a string for the browser.', tags: ['Props', 'Style'] },
  { q: 'What is rendered?\n\n```jsx\nfunction Greet({ name = "Guest" }) {\n  return <p>{name}</p>;\n}\n<Greet />;\n```', opts: ['empty', 'Guest', 'undefined', 'an error'], a: 1, e: '<Greet /> passes no name, so props.name is undefined, and a destructuring default applies exactly when the value is undefined; name becomes Guest and the paragraph shows Guest. Rendering undefined would show nothing rather than the text undefined, and a missing prop is not an error.', intro: 'Nothing is passed for name. Look at the parameter list for what happens in that case.', tags: ['Props', 'Defaults'] },
  { q: 'What does Card render around its content?\n\n```jsx\nfunction Card({ children }) {\n  return <div className="card">{children}</div>;\n}\n<Card>Hi</Card>;\n```', opts: ['"Hi" inside the div', 'the word "children"', 'Nothing', 'an error'], a: 0, e: 'React passes the content nested between a component\'s opening and closing tags as props.children, so {children} renders the text Hi inside div.card. It is an expression, not literal text, so the word children never appears, and an element with text between its tags is normal, not an error.', intro: 'Whatever sits between <Card> and </Card> arrives in the component through one specific prop. Find where that prop is placed.', tags: ['Props', 'children'] },

  // ── Level 4 — Rendering Lists ──────────────────────────────────────────
  { q: 'How many list items render?\n\n```jsx\nconst items = ["a", "b", "c"];\n<ul>{items.map(i => <li key={i}>{i}</li>)}</ul>;\n```', opts: ['1', '3', '0', 'an error'], a: 1, e: 'items.map returns an array of three li elements, and React renders an array child by rendering every element in order, so three list items appear. Each has a key (the string itself, unique here), so there is no key warning and no error.', intro: 'map returns a new array with one result per input element. Count what ends up inside the ul.', tags: ['Lists', 'map'] },
  { q: 'What is missing here?\n\n```jsx\n{items.map(i => <li>{i}</li>)}\n```', opts: ['A key prop', 'A return', 'A ref', 'Nothing'], a: 0, e: 'Elements created in a loop need a key prop (for example <li key={i}>) so React can match each item to the same DOM node on the next render; without it React warns "Each child in a list should have a unique key prop" and may reorder or reset state incorrectly when the list changes. The arrow function returns the li implicitly, and refs are not needed for lists.', intro: 'React renders this list but logs a warning in the console. Recall what every element produced by map should carry.', tags: ['Lists', 'key'] },
  { q: 'What is rendered?\n\n```jsx\nconst nums = [1, 2, 3];\n<div>{nums.map(n => n * 2)}</div>;\n```', opts: ['246', '123', '[2, 4, 6]', 'an error'], a: 0, e: 'map returns [2, 4, 6], and React renders an array child item by item, so the three numbers become adjacent text nodes and the div reads 246. React does not stringify the array (that would give 2,4,6), and arrays of plain numbers or strings render without a key warning because keys are checked only on elements.', intro: 'First work out the array map produces, then recall how React displays an array of numbers when none of them is wrapped in an element.', tags: ['Lists', 'map'] },
  { q: 'What is rendered?\n\n```jsx\nconst empty = [];\n<ul>{empty.map(i => <li key={i}>{i}</li>)}</ul>;\n```', opts: ['An empty list', 'an error', 'undefined', '"[]"'], a: 0, e: 'empty.map returns a new empty array, and React renders an empty array as no children, so the ul is rendered with nothing inside. No error occurs (map on an empty array is safe), undefined is never produced, and React does not print the array literal.', intro: 'map over zero elements still returns an array. Consider what React renders for an array with nothing in it.', tags: ['Lists'] },

  // ── Level 5 — Conditional Rendering ────────────────────────────────────
  { q: 'What is rendered?\n\n```jsx\nconst loggedIn = true;\n<div>{loggedIn ? "Welcome" : "Sign in"}</div>;\n```', opts: ['Welcome', 'Sign in', 'true', 'an error'], a: 0, e: 'The braces evaluate the ternary: loggedIn is true, so the expression yields "Welcome" and that text is rendered. "Sign in" is the false branch, the boolean itself is never displayed, and a ternary is valid inside JSX because it is an expression, unlike an if statement.', intro: 'A ternary is an expression, so it can sit inside braces. Evaluate it with loggedIn = true before you look at the div.', tags: ['Conditional'] },
  { q: 'What is rendered?\n\n```jsx\nconst show = false;\n<div>{show && <p>Hi</p>}</div>;\n```', opts: ['<p>Hi</p>', 'Nothing', '"false"', 'an error'], a: 1, e: 'false && <p>Hi</p> evaluates to false, because && returns its left operand when that operand is falsy, and React ignores boolean children, so the div renders empty. The paragraph is never created, the text false is not shown, and no error occurs; this is why && is a common conditional-rendering idiom.', intro: 'Work out what the && expression evaluates to in JavaScript first, then recall how React treats that value as a child.', tags: ['Conditional', 'Short-circuit'] },
  { q: 'What does this render?\n\n```jsx\nconst count = 0;\n<div>{count && <p>Has items</p>}</div>;\n```', opts: ['Nothing', '0', '<p>Has items</p>', 'an error'], a: 1, e: 'count && <p>Has items</p> evaluates to 0, because && returns its left operand when it is falsy; React skips only null, undefined and booleans, and a number is rendered as text, so the div shows 0. Nothing would appear only if the left side were false or null, which is why the safe forms are count > 0 && ... or a ternary.', intro: 'Both operands matter here: && returns its left operand when that operand is falsy. Then remember which falsy values React skips and which it displays.', tags: ['Conditional', 'Gotchas'] },
  { q: 'What is rendered?\n\n```jsx\nconst items = ["a"];\n<div>{items.length > 0 && <p>{items.length}</p>}</div>;\n```', opts: ['1', 'Nothing', '0', 'an error'], a: 0, e: 'items.length is 1, so items.length > 0 is true and && returns its right operand, the paragraph, which renders the length 1. Nothing would render only if the comparison were false, and 0 could appear only if the left side were a raw length of an empty array rather than a comparison, which is exactly why comparing to 0 is the safer pattern.', intro: 'Evaluate the comparison on the left of && first; only then decide whether the right side is created and what it contains.', tags: ['Conditional'] },

  // ── Level 6 — useState: Basics ─────────────────────────────────────────
  { q: 'What is the initial value of count?\n\n```jsx\nconst [count, setCount] = useState(0);\n```', opts: ['0', 'undefined', 'null', 'setCount'], a: 0, e: 'The argument passed to useState is the initial state, so on the first render count is 0; React then keeps the latest value across re-renders. It is not undefined or null unless you pass those, and setCount is the second element of the returned pair, the function used to update count.', intro: 'useState takes one argument and returns a pair. Recall what the argument is used for on the very first render.', tags: ['useState'] },
  { q: 'What is the value of name?\n\n```jsx\nconst [name] = useState("Sam");\n```', opts: ['Sam', 'undefined', '[]', 'useState'], a: 0, e: 'The first array element is the current state value, "Sam".', tags: ['useState'] },
  { q: 'What is state[1]?\n\n```jsx\nconst state = useState(0);\nstate[1];\n```', opts: ['0', 'the setter function', 'undefined', 'an array'], a: 1, e: 'useState returns a two-element array: index 0 holds the current state (0 here) and index 1 holds the setter function, so state[1] is the function you would normally name setState. Destructuring const [value, setValue] = useState(0) is just the usual way of reading those two positions; index 1 is neither undefined nor an array.', intro: 'Without destructuring you see the raw return value of useState. Work out its shape, then read index 1.', tags: ['useState'] },
  { q: 'What type is setOn?\n\n```jsx\nconst [on, setOn] = useState(false);\n```', opts: ['boolean', 'a function', 'false', 'undefined'], a: 1, e: 'The second value from useState is the updater function.', tags: ['useState'] },

  // ── Level 7 — Event Handling ───────────────────────────────────────────
  { q: 'When does it log "clicked"?\n\n```jsx\n<button onClick={() => console.log("clicked")}>Go</button>;\n```', opts: ['On render', 'When clicked', 'Never', 'On mount'], a: 1, e: 'onClick receives the arrow function itself, so React stores it as the click handler and calls it only when the button is clicked. Nothing is logged during render or on mount because the function is defined there but not invoked; it would run at render time only if it were written as onClick={console.log("clicked")}, which calls it immediately.', intro: 'Look at what is passed to onClick: a function definition, not a function call. Consider when React invokes it.', tags: ['Events'] },
  { q: 'What is the problem here?\n\n```jsx\n<button onClick={handleClick()}>Go</button>;\n```', opts: ['handleClick runs immediately on render', 'It works fine', 'It never runs', 'Syntax error'], a: 0, e: 'handleClick() calls the function while the component renders and passes its return value (usually undefined) to onClick, so the code runs at render time and nothing happens on click. It is valid syntax, so there is no error, but it is not correct; pass the function itself, onClick={handleClick}, or an arrow such as onClick={() => handleClick(id)} when arguments are needed. If handleClick set state, the render-time call would also cause an infinite re-render loop.', intro: 'Look at the parentheses after handleClick and ask what the expression inside the braces evaluates to before React sees it.', tags: ['Events', 'Gotchas'] },
  { q: 'After one click, what does the button show?\n\n```jsx\nfunction App() {\n  const [n, setN] = useState(0);\n  return <button onClick={() => setN(n + 1)}>{n}</button>;\n}\n```', opts: ['0', '1', '2', '01'], a: 1, e: 'The click calls setN(0 + 1), so React schedules a re-render in which n is 1 and the button shows 1. It does not stay at 0: the setter changes what the next render receives, even though n itself is unchanged inside the handler. Only one update is queued per click, so 2 is impossible, and n is a number, so "01" cannot appear.', intro: 'The button shows n from the current render. Decide what the click asks React to use for the next render, and whether the setter runs more than once.', tags: ['Events', 'useState'] },
  { q: 'In this handler, what does e.target.value hold?\n\n```jsx\n<input onChange={e => console.log(e.target.value)} />;\n```', opts: ['The current text of the input', 'The input element itself', 'undefined, because inputs have no value until submit', 'The name of the event ("change")'], a: 0, e: 'The change event\'s target is the <input> element, and an input element\'s value property holds its current text, so e.target.value is what the user has typed so far. e.target on its own is the element, not its text; the event\'s name lives in e.type, and the value exists at every keystroke, not only at submit.', intro: 'e.target is whatever element fired the event. Decide what that element is here, then what its value property contains.', tags: ['Events', 'Forms'] },

  // ── Level 8 — Updating State ───────────────────────────────────────────
  { q: 'After the click handler runs and the component re-renders, what is n?\n\n```jsx\nconst [n, setN] = useState(0);\nfunction handleClick() {\n  setN(5);\n}\n// user clicks a button wired to handleClick\n```', opts: ['0', '5', 'undefined', 'NaN'], a: 1, e: 'setN(5) does not change n in the handler that is running; it tells React to schedule a re-render in which n is 5, so after that re-render n is 5. It is not still 0 because React applies the queued update before rendering again, and nothing here produces undefined or NaN.', intro: 'The handler asks for one specific value. Decide whether the setter changes n inside the running handler or only tells React what the next render should use.', tags: ['useState'] },
  { q: 'What does React pass as prev when this updater runs?\n\n```jsx\nsetN(prev => prev + 1);\n```', opts: ['The value the update will produce', 'The latest state, including updates already queued', 'undefined, because updaters take no input', 'The setter function itself'], a: 1, e: 'React queues the updater and, when it processes the queue for the next render, calls it with the most recent value of n — including any updates queued earlier in the same event — and stores what it returns. prev is therefore the input, not the result, and it is always a real value, never undefined.', intro: 'The arrow has a parameter and a return value. Think about which value React holds for n at the moment it applies this update.', tags: ['useState'] },
  { q: 'After one call of handle, what does the next render show for n?\n\n```jsx\nconst [n, setN] = useState(0);\nfunction handle() {\n  setN(n + 1);\n  setN(n + 1);\n}\n```', opts: ['1', '2', '0', '3'], a: 0, e: 'Both calls compute n + 1 with the n from the current render, which is 0, so both queue "set n to 1" and the next render shows 1. The setter does not change the n variable in the running handler, so the second call cannot see 1. To build on the in-flight value you pass an updater, setN(n => n + 1), which is what makes 2 possible.', intro: 'n is a plain number captured when this render ran. Ask whether the second setN can see anything the first one changed.', tags: ['useState', 'Gotchas'] },
  { q: 'After one call of handle from n = 0, what does the next render show for n?\n\n```jsx\nfunction handle() {\n  setN(p => p + 1);\n  setN(p => p + 1);\n}\n```', opts: ['1', '2', '0', '3'], a: 1, e: 'React queues both updater functions and runs them in order during the next render: the first receives 0 and returns 1, the second receives that 1 and returns 2. Unlike setN(n + 1), which would capture the render\'s n twice and give 1, updaters always receive the latest queued value.', intro: 'Each call hands React a function instead of a number. Think about what React feeds into the second function after it has run the first.', tags: ['useState'] },

  // ── Level 9 — State with Objects/Arrays ────────────────────────────────
  { q: 'What is the resulting user?\n\n```jsx\nconst [user, setUser] = useState({ name: "A", age: 1 });\nsetUser({ ...user, age: 2 });\n```', opts: ['{ name: "A", age: 2 }', '{ age: 2 }', '{ name: "A", age: 1 }', 'An error, because state objects are read-only'], a: 0, e: '{ ...user, age: 2 } copies name and age from the old object and then overrides age, giving a new object { name: "A", age: 2 }, which React stores. { age: 2 } is what you would get without the spread, and { name: "A", age: 1 } would need the override to come before the spread. Nothing throws: state is treated as read-only by convention, and this code never mutates it.', intro: 'Read the object literal left to right: the spread copies every key first, and anything written after it overrides the same key.', tags: ['useState', 'Objects'] },
  { q: 'What is the new list?\n\n```jsx\nconst [list, setList] = useState([1, 2]);\nsetList([...list, 3]);\n```', opts: ['[1, 2, 3]', '[3]', '[1, 2]', 'an error'], a: 0, e: 'Spreading the old list and adding 3 produces [1, 2, 3].', tags: ['useState', 'Arrays'] },
  { q: 'Why might the UI not update?\n\n```jsx\nconst [list, setList] = useState([1, 2]);\nlist.push(3);\nsetList(list);\n```', opts: ['setList receives the same array object, so React sees no change and skips the re-render', 'push returns the new length, so setList receives 3 instead of the array', 'Arrays stored in state are frozen, so push throws before setList runs', 'It always updates; React re-renders on every setter call regardless of value'], a: 0, e: 'push changes the array in place, so setList(list) hands React the very same object it already has; React compares with Object.is, decides the state is unchanged and skips the re-render, so the 3 never shows. The fix is a new array: setList([...list, 3]). push does return a length, but this code passes list, not push\'s return value, and state arrays are not frozen.', intro: 'Compare the value React is given with the value it already holds — not the contents, the identity of the array.', tags: ['useState', 'Immutability'] },
  { q: 'What is the new list?\n\n```jsx\nconst [list, setList] = useState([1, 2, 3]);\nsetList(list.filter(x => x !== 2));\n```', opts: ['[1, 3]', '[2]', '[1, 2, 3]', '[1, 2]'], a: 0, e: 'filter builds a new array from the elements that pass the test, so 1 and 3 stay and 2 is dropped: [1, 3]. [2] would be the result of x === 2. The original list is left untouched, which is exactly why filter is the right tool for removing from state: React receives a new reference and re-renders.', intro: 'filter keeps the elements for which the callback is true. Check what x !== 2 returns for each element, and whether filter touches the original array.', tags: ['useState', 'Arrays'] },

  // ── Level 10 — Derived State ───────────────────────────────────────────
  { q: 'Should count be its own state?\n\n```jsx\nconst [items, setItems] = useState([1, 2, 3]);\nconst count = items.length;\n```', opts: ['Yes, use useState', 'No, derive it from items', 'Use a ref', 'Use useEffect'], a: 1, e: 'Values computable from existing state should be derived, not stored separately.', tags: ['Derived state'] },
  { q: 'What is full, and what happens to it when setFirst("Z") runs?\n\n```jsx\nconst [first, setFirst] = useState("A");\nconst [last] = useState("B");\nconst full = `${first} ${last}`;\n```', opts: ['"A B" now, and it is recomputed to "Z B" on the next render', '"A B" now, and it keeps that value until you call a setter for it', '"AB" now, because a template literal drops surrounding spaces', 'undefined, because full was never registered with useState'], a: 0, e: 'The template literal joins the two values with the space typed between them, so full is "A B". Because it is computed in the component body, the render after setFirst("Z") rebuilds it as "Z B" — there is nothing to keep in sync and no setter to call. The space is part of the literal, so "AB" would need `${first}${last}`.', intro: 'Notice where full is declared: in the component body, not with useState. Then ask what setFirst does to that body.', tags: ['Derived state'] },
  { q: 'What is total?\n\n```jsx\nconst [price] = useState(10);\nconst [qty] = useState(2);\nconst total = price * qty;\n```', opts: ['10', '20', '2', '12'], a: 1, e: 'total is derived from price * qty = 20.', tags: ['Derived state'] },
  { q: 'What is evens, and what does React actually store?\n\n```jsx\nconst [nums, setNums] = useState([1, 2, 3, 4]);\nconst evens = nums.filter(n => n % 2 === 0);\n```', opts: ['[2, 4], rebuilt from nums on each render; only nums is state', '[2, 4], held alongside nums as a second piece of state', '[1, 3], because filter keeps the elements that fail the test', '[1, 2, 3, 4], because filter returns the array unchanged without a second argument'], a: 0, e: 'n % 2 === 0 is true for 2 and 4, so evens is [2, 4]. It is a plain const recomputed on every render from nums, so there is no second piece of state that could disagree with the source — that is what makes a derived list safe. filter keeps the elements that pass, not the ones that fail, and it never mutates nums.', intro: 'Run the callback in your head for each of the four numbers, then ask which values in this component React is actually tracking.', tags: ['Derived state'] },

  // ── Level 11 — useEffect: Basics ───────────────────────────────────────
  { q: 'When does this log "mounted"?\n\n```jsx\nuseEffect(() => {\n  console.log("mounted");\n}, []);\n```', opts: ['Once, after the first render is committed', 'After every render', 'Before the first render, so the log appears first', 'Only when the component is removed'], a: 0, e: 'With [] there is no dependency that can differ, so React runs the setup once after the first commit and not again while the component stays mounted. It cannot run before the render, because the effect only exists once the component body has run. In development inside <StrictMode> React deliberately runs setup, cleanup and setup again, so the log appears twice there; production runs it once.', intro: 'The array lists what the effect watches. An empty list means nothing it watches can ever change.', tags: ['useEffect'] },
  { q: 'When does this effect run?\n\n```jsx\nuseEffect(() => {\n  console.log("ran");\n});\n```', opts: ['Once, after the first render', 'After every render of the component', 'Only when a value used inside it changes', 'Only when the component is removed'], a: 1, e: 'With no dependency array React has nothing to compare against the previous commit, so it runs the effect after every one — the first render and every update. It does not read the body and infer the dependencies, which is why "only when a value inside changes" is wrong; you get that behavior only by listing the values yourself.', intro: 'There is no second argument at all. Ask what React has to compare when nothing was listed.', tags: ['useEffect'] },
  { q: 'When does this effect run?\n\n```jsx\nuseEffect(() => {\n  console.log(count);\n}, [count]);\n```', opts: ['Only after the first render, then never again', 'After the first render and after any render where count changed', 'After every render, whether or not count changed', 'Only when the component is removed from the page'], a: 1, e: 'React compares each dependency with its value at the previous commit, so the effect runs after the first render and again whenever count differs. A render caused by other state leaves count equal, so the effect is skipped — that is exactly what an omitted array gives up, since it re-runs after every commit. In development inside <StrictMode> React adds one extra setup and cleanup pass, so the mount run shows up twice.', intro: 'The array lists what the effect watches, and count is the only entry. Picture a render caused by some other piece of state.', tags: ['useEffect'] },
  { q: 'What does the paragraph end up showing, and does 0 ever reach the DOM?\n\n```jsx\nfunction App() {\n  const [n, setN] = useState(0);\n  useEffect(() => {\n    setN(1);\n  }, []);\n  return <p>{n}</p>;\n}\n```', opts: ['1, after a first commit that showed 0', '1, and 0 is never committed because the effect runs first', '0, because an empty dependency array discards the update', 'Nothing: setting state inside an effect throws'], a: 0, e: 'React renders with n = 0 and commits <p>0</p>, then runs the effect, which sets n to 1 and triggers a second render showing <p>1</p>. So the final DOM is <p>1</p> but 0 was on screen first — that extra pass is why an initial value that is really derived belongs in useState\'s initializer rather than in an effect. The empty array does not cancel the update; it only stops the effect from running again.', intro: 'Effects run after the commit, not during it. Ask what the DOM already holds at the moment the effect is allowed to run.', tags: ['useEffect', 'useState'] },

  // ── Level 12 — Effect Dependencies ─────────────────────────────────────
  { q: 'value is a prop that changes over time. What does this effect do?\n\n```jsx\nuseEffect(() => {\n  console.log(value);\n}, []);\n```', opts: ['Logs the value from the first render and never logs again', 'Logs the current value after every change', 'Logs nothing, because the dependency array is empty', 'Fails the build, because value is not listed'], a: 0, e: 'With [] the setup runs once, so the only function React holds is the closure from the first render: it logs that render\'s value and is never called again. React does not re-read value in between — the closure is the whole story. An empty array does not silence the effect, and a missing dependency is a lint warning, not a build failure. In development inside <StrictMode> that first log appears twice, still with the first render\'s value.', intro: 'The empty array fixes when the effect runs. Ask which render\'s value the function React kept belongs to.', tags: ['useEffect', 'Dependencies'] },
  { q: 'What happens once this component mounts?\n\n```jsx\nuseEffect(() => {\n  setCount(count + 1);\n}, [count]);\n```', opts: ['It renders once and settles, because the effect runs only on mount', 'It re-renders without stopping: each run changes the dependency that triggers it', 'It runs twice and then React ignores the repeated update', 'It never runs, because count has not changed yet at mount'], a: 1, e: 'The effect runs after the first commit, sets count, which changes its only dependency, so it runs again — and again. In development React logs "Maximum update depth exceeded", but it does not stop the component, so the loop is yours to break: compute the value during render instead, or depend on something the effect does not itself change.', intro: 'Write down what the effect changes, then check that value against the array underneath it.', tags: ['useEffect', 'Gotchas'] },
  { q: 'Why does this effect run after every render?\n\n```jsx\nuseEffect(fetchUser, [{ id }]);\n```', opts: ['The object literal is a new reference every render, so the comparison always differs', 'React compares dependency objects field by field and { id } has no stable field', 'An object dependency turns the comparison off and forces the effect to run', 'Objects are not allowed in the array, so React falls back to no array at all'], a: 0, e: 'Each render evaluates `{ id }` afresh and produces a different object; React compares dependencies with Object.is, which is false for two distinct objects even when their fields match, so every render looks like a change and fetchUser runs again. The comparison is by reference, never field by field — depend on the primitive ([id]) or memoize the object with useMemo.', intro: 'The array is rebuilt whenever the component body runs. Ask what `{ id }` evaluates to on the second render.', tags: ['useEffect', 'Dependencies'] },
  { q: 'When does this run?\n\n```jsx\nuseEffect(() => {\n  document.title = `Count: ${count}`;\n}, [count]);\n```', opts: ['Every render', 'On mount and when count changes', 'Never', 'On unmount'], a: 1, e: 'The effect runs on mount and whenever count changes.', tags: ['useEffect', 'Dependencies'] },

  // ── Level 13 — Cleanup Functions ───────────────────────────────────────
  { q: 'What is the returned function for, and when does React call it?\n\n```jsx\nuseEffect(() => {\n  const id = setInterval(tick, 1000);\n  return () => clearInterval(id);\n}, []);\n```', opts: ['It is the cleanup, and React calls it when the component unmounts', 'It is the cleanup, and React calls it before every render', 'It is a retry React calls if the effect throws', 'It is just the effect\'s return value and React ignores it'], a: 0, e: 'A function returned from an effect is its cleanup: React runs it before the effect runs again and once when the component unmounts. With [] the effect never re-runs, so here the only call is at unmount — without it the interval would keep firing after the component is gone. React does not ignore the return value; returning something that is not a function warns and then throws. In development inside <StrictMode> you also see one extra setup/cleanup pair.', intro: 'The interval outlives the render that started it. Ask who stops it, and when.', tags: ['useEffect', 'Cleanup'] },
  { q: 'id changes from 1 to 2. In what order do the logs appear?\n\n```jsx\nuseEffect(() => {\n  console.log("setup");\n  return () => console.log("cleanup");\n}, [id]);\n```', opts: ['setup, cleanup, setup', 'setup, setup, cleanup', 'setup, setup', 'setup, cleanup'], a: 0, e: 'React runs the cleanup for the previous dependency value before the setup for the new one, so the order is setup (id 1), cleanup (id 1), setup (id 2), with a final cleanup at unmount. Running both setups without a cleanup between them would leave the id 1 subscription live — the classic duplicate-connection bug. In development inside <StrictMode> an extra setup/cleanup pair appears at mount.', intro: 'React never leaves two setups live at once. Ask what has to happen to the old one before id 2 is connected.', tags: ['useEffect', 'Cleanup'] },
  { q: 'What goes wrong if the returned line is deleted?\n\n```jsx\nuseEffect(() => {\n  window.addEventListener("resize", onResize);\n  return () => window.removeEventListener("resize", onResize);\n}, []);\n```', opts: ['The listener stays on window after unmount and keeps running a handler for a component that is gone', 'Nothing: React removes the listener itself when it unmounts the component', 'Resize events stop reaching every other listener on the page', 'React re-runs the effect on every render to compensate'], a: 0, e: 'window is not owned by React, so anything the effect registers there survives unmount unless the cleanup removes it: the handler keeps firing, it keeps the render\'s closure alive, and each remount adds another one. React removes the DOM nodes it created, not the listeners you attached to window yourself. Other listeners on the page are unaffected either way.', intro: 'window outlives the component. Ask who still holds a reference to onResize once the component is gone.', tags: ['useEffect', 'Cleanup'] },
  { q: 'What is wrong with this effect?\n\n```jsx\nuseEffect(() => {\n  const id = setInterval(() => setN(n => n + 1), 1000);\n}, []);\n```', opts: ['Nothing runs, because the effect returns no cleanup', 'The interval is never cleared, so it keeps ticking after the component unmounts', 'The updater form makes each tick overwrite the previous one', 'The empty array stops the interval from ever starting'], a: 1, e: 'setInterval keeps firing until something calls clearInterval, and nothing here ever does: after unmount the callback still runs for a component that no longer exists, and every remount adds another timer. Returning () => clearInterval(id) fixes it. The rest of the snippet is right — the empty array keeps the effect from re-running on later renders, and setN(n => n + 1) is the correct form for a callback that cannot see the current n. In development inside <StrictMode> the effect runs twice at mount, so the missing cleanup already leaves two timers going.', intro: 'id is stored and never used again. Ask what stops the timer once the component goes away.', tags: ['useEffect', 'Cleanup'] },

  // ── Level 14 — useRef ──────────────────────────────────────────────────
  { q: 'Clicking the button sets ref.current to 5. Does the component re-render?\n\n```jsx\nfunction Counter() {\n  const ref = useRef(0);\n  return <button onClick={() => { ref.current = 5; }}>set</button>;\n}\n```', opts: ['Yes - a ref is state, so React schedules a render', 'No - React is never told the value changed', 'Yes, but only after the current event handler finishes', 'No, and the value resets to 0 on the next render'], a: 1, e: 'A ref is a plain JavaScript object, so writing ref.current mutates it and React has no way of knowing - react.dev puts it as \'Changing a ref does not trigger a re-render.\' The value is not lost either: useRef hands back the same object on every render, so it survives, unlike a local variable that would be recreated. Measured on this component: after the click, ref.current was 5 and the render count was still 1.', intro: 'Two separate questions are packed into these options: whether the value sticks, and whether the screen updates. Settle them one at a time.', tags: ['useRef'] },
  { q: 'What does the effect log after the component mounts?\n\n```jsx\nfunction Field() {\n  const inputRef = useRef(null);\n  useEffect(() => { console.log(inputRef.current); }, []);\n  return <input ref={inputRef} />;\n}\n```', opts: ['null', 'the DOM input element', '0', 'a function'], a: 1, e: 'During render the ref object holds the initial value you passed, null. After React has created the DOM node and put it on the screen it sets ref.current to that node, so by the time the effect runs it is the <input> element and you can call inputRef.current.focus() on it. null is what you would read during the first render, before the node exists, and React sets it back to null when the node is removed.', intro: 'The ref object exists from the first render, but something has to happen in the DOM before React can fill it in.', tags: ['useRef', 'DOM'] },
  { q: 'What is this pattern commonly used for?\n\n```jsx\nconst renders = useRef(0);\nuseEffect(() => { renders.current++; });\n```', opts: ['forcing the component to re-render on every change', 'keeping a value between renders without causing a re-render', 'storing a value that should appear in the rendered output', 'sharing one value between every instance of the component'], a: 1, e: 'useRef returns the same object on every render, so renders.current keeps its value between renders, and mutating it never schedules one - which is exactly what a counter like this needs. A local variable would restart at 0 on every render, and a module-level variable would be shared by every mounted instance. State would be worse: setting it in an effect with no dependency array re-renders, which re-runs the effect, until React reports \'Maximum update depth exceeded\'. Note the placement: react.dev says to read and write ref.current in effects or event handlers, not during render.', intro: 'Try the same counter with a plain local variable, then with state. What goes wrong in each case is what this pattern exists to avoid.', tags: ['useRef'] },
  { q: 'What is rendered?\n\n```jsx\nconst ref = useRef(10);\nfunction Comp() {\n  ref.current = 20;\n  return <p>{ref.current}</p>;\n}\n```', opts: ['10', '20', 'undefined', 'an error'], a: 1, e: 'ref.current is set to 20 before the return, so the paragraph shows 20.', tags: ['useRef'] },

  // ── Level 15 — Forms & Inputs ──────────────────────────────────────────
  { q: 'What kind of input is this?\n\n```jsx\nconst [text, setText] = useState("");\n<input value={text} onChange={e => setText(e.target.value)} />;\n```', opts: ['an uncontrolled input - the DOM keeps the current text', 'a controlled input - React state keeps the current text', 'a read-only input - the value prop blocks typing', 'an invalid input - value and onChange cannot be combined'], a: 1, e: 'The field renders whatever is in state and every keystroke calls setText, so React is the single source of truth and re-renders the input with the new text - that is what controlled means. An uncontrolled input has no value prop and keeps its text in the DOM, where you read it with defaultValue plus a ref. It is not read-only either: value together with onChange is exactly the pair React expects.', intro: 'Look at where the text actually lives between keystrokes, and what puts it back into the field.', tags: ['Forms'] },
  { q: 'What is the problem?\n\n```jsx\n<input value="hi" />;\n```', opts: ['it works normally - React updates the value as you type', 'the field ignores typing and React warns in the console', 'React treats it as uncontrolled and keeps the typed text', 'React throws an error when the input first renders'], a: 1, e: 'A value prop with no onChange makes the field read-only in practice: React re-renders it with \'hi\' after every keystroke, so the typed text is thrown away, and it warns \'You provided a value prop to a form field without an onChange handler. This will render a read-only field. If the field should be mutable use defaultValue. Otherwise, set either onChange or readOnly.\' It is not uncontrolled - the value prop is what makes it controlled - and nothing crashes. Use defaultValue for a field the DOM owns, or add onChange to make it editable.', intro: 'Something has to put the typed characters back into the field. Ask what this element is missing.', tags: ['Forms', 'Gotchas'] },
  { q: 'What does e.target.checked give?\n\n```jsx\nconst [checked, setChecked] = useState(false);\n<input type="checkbox" checked={checked} onChange={e => setChecked(e.target.checked)} />;\n```', opts: ['the value string', 'the boolean checked state', 'undefined', 'the element'], a: 1, e: 'For a checkbox the boolean lives on e.target.checked, so setChecked(e.target.checked) mirrors the box into state and the checked prop drives it back - the same contract that value and onChange give a text input. e.target.value is a different thing: it is the string submitted with the form, \'on\' by default unless you set a value attribute, and it does not change when the box is ticked. Measured on a real click: e.target.checked === true (typeof \'boolean\'), e.target.value === \'on\'.', intro: 'A checkbox carries both a value and a ticked state. Ask which of the two changes when the user clicks it.', tags: ['Forms'] },
  { q: 'Why call preventDefault?\n\n```jsx\n<form onSubmit={e => { e.preventDefault(); }}>\n```', opts: ['it stops the browser\'s default submit, which loads a new page', 'it sends the form data with fetch instead of a page load', 'it stops the submit event from reaching parent elements', 'it clears the inputs once the handler has finished'], a: 0, e: 'Submitting a form is a navigation: the browser sends it and loads a new document, which tears down the React tree and every piece of state in it. preventDefault cancels that default action so your handler can send the data itself, usually with fetch. It does not send anything on its own, and it does not stop the event traveling up the tree - that is stopPropagation, a different method.', intro: 'Ask what the browser would do with this form if no JavaScript ran at all.', tags: ['Forms'] },

  // ── Level 16 — Lifting State Up ────────────────────────────────────────
  { q: 'Where does the state live?\n\n```jsx\nfunction Parent() {\n  const [value, setValue] = useState("");\n  return <Child value={value} onChange={setValue} />;\n}\n```', opts: ['in Child, because Child is what displays it', 'in Parent, which passes the value and the setter down', 'in both - Child receives its own copy of the state', 'in React itself, outside either component'], a: 1, e: 'useState is called in Parent, so Parent owns both the value and the setter; Child receives them as props for this render only. Nothing is copied: Child re-renders with whatever Parent passes next and can ask for a change only by calling onChange. One owner and a downward flow is exactly what lifting state up produces.', intro: 'Ask whether passing a value as a prop copies it into the child or only lends it for this render.', tags: ['Lifting state'] },
  { q: 'How does Child change count?\n\n```jsx\nfunction Child({ count, onInc }) {\n  return <button onClick={onInc}>{count}</button>;\n}\n```', opts: ['by calling setCount, which React exposes to every child', 'by calling the onInc function it received as a prop', 'by keeping its own useState and updating that instead', 'by assigning a new value to props.count directly'], a: 1, e: 'Child gets count to display and onInc to call. Props are read-only, so calling onInc is the only way it can ask for a change: the parent runs the setter and sends a new count down on the next render. Assigning to props.count fails either way: in development React freezes props, so the line throws a TypeError, and where it does not throw React never reads that object again. Giving Child its own useState would create a second value the parent never sees.', intro: 'Child has only what it was handed. Look at the two names in its props and ask which one can change anything.', tags: ['Lifting state'] },
  { q: 'To share state between two sibling components you should:', opts: ['keep a copy in each sibling and update both on change', 'move the state to their closest common parent and pass it down', 'store it in a module-level variable that both siblings import', 'have one sibling read the other\'s value through a ref'], a: 1, e: 'Data flows downward, so the only component that can feed both siblings is one above them: put the state in their closest common parent and pass the value down with a callback for changes. Two copies drift apart as soon as one is updated without the other. A module-level variable is shared but invisible to React, so writing to it re-renders nothing, and a ref gives one sibling a handle to something, not a subscription to it.', intro: 'React data flows one way. Ask what each of these options would do the moment one sibling changes the value.', tags: ['Lifting state'] },
  { q: 'When Nav calls onSelect("about"), what tab does Content get?\n\n```jsx\nfunction App() {\n  const [tab, setTab] = useState("home");\n  return (\n    <>\n      <Nav onSelect={setTab} />\n      <Content tab={tab} />\n    </>\n  );\n}\n```', opts: ['"home"', '"about"', 'undefined', 'an error'], a: 1, e: 'App passes setTab itself as onSelect, so calling onSelect(\'about\') is calling the state setter: tab becomes \'about\', App re-renders, and Content receives the new value. \'home\' is only the initial state - it would stay the answer if Nav updated something App did not own, which is the mistake this tests. Content holds no state of its own; it updates purely because its prop changed.', intro: 'Follow what App actually passed as onSelect, then ask what re-renders once tab changes.', tags: ['Lifting state'] },

  // ── Level 17 — useMemo ─────────────────────────────────────────────────
  { q: 'When does expensiveCalc run?\n\n```jsx\nconst result = useMemo(() => expensiveCalc(a), [a]);\n```', opts: ['on every render, because the arrow function is recreated each time', 'on the first render, and again whenever a changes', 'never, unless you call result() yourself', 'once on mount and once more when the component unmounts'], a: 1, e: 'useMemo calls the function on the first render and after that only when a dependency differs by Object.is; otherwise it returns the stored value. Measured: one call at mount, still one after a re-render with the same a, two after a changed to 3. Two caveats belong with this: in development Strict Mode React runs the calculation twice to expose impure code, and react.dev warns that React may throw the cached value away, so useMemo is a performance optimization and never a correctness guarantee.', intro: 'The arrow function is created on every render, but creating it is not calling it. Ask what decides whether it is called.', tags: ['useMemo'] },
  { q: 'What is value?\n\n```jsx\nconst value = useMemo(() => 2 + 2, []);\n```', opts: ['4', '"2+2"', 'a function', 'undefined'], a: 0, e: 'useMemo calls the function you give it and returns that result, so value is the number 4; the function is only the recipe. useCallback is the hook that hands the function itself back - that is the whole difference between the two. And 2 + 2 is not worth memoizing: reach for useMemo when the work is genuinely expensive or when a reference has to stay stable.', intro: 'Two things could come back from this call: the function you passed, or what running it produced. Ask which one the hook keeps.', tags: ['useMemo'] },
  { q: 'Why use useMemo here?\n\n```jsx\nconst sorted = useMemo(() => [...items].sort(compare), [items]);\n```', opts: ['To re-sort on every render', 'To avoid re-sorting unless items changes', 'To mutate items', 'It has no effect'], a: 1, e: 'Sorting is O(n log n) work that depends only on items, so useMemo does it once and reuses the result until items changes by reference - measured here as one sort across two renders. The spread is a separate point: sort mutates in place, so [...items] keeps the prop intact. Watch the dependency, though: if the parent builds a new array literal on every render, items is a new reference each time and the memo never hits.', intro: 'This line runs on every render. Ask which part of it actually does work each time, and which part might not.', tags: ['useMemo'] },
  { q: 'Across renders (with no dep changes), what is a?\n\n```jsx\nconst a = useMemo(() => ({ x: 1 }), []);\n```', opts: ['A new object each render', 'The same object reference', 'undefined', 're-created on any state change'], a: 1, e: 'With an empty dep array, useMemo keeps returning the same object reference.', tags: ['useMemo'] },

  // ── Level 18 — useCallback ─────────────────────────────────────────────
  { q: 'What does useCallback return?\n\n```jsx\nconst handleClick = useCallback(() => doThing(id), [id]);\n```', opts: ['the result of calling doThing(id)', 'the same function on every render, until id changes', 'a new function on every render, like an inline arrow', 'a copy of the function with id bound as an argument'], a: 1, e: 'useCallback returns the function, not its result: on the first render you get exactly the function you passed, and on later renders the same one back while every dependency compares equal by Object.is - measured here, identity held while id stayed 1 and changed when id became 2. An inline arrow would be a new object every render, which is what makes memo children re-render and effects re-run. Nothing is called and no arguments are bound.', intro: 'Compare it with writing the arrow inline: what would differ between two consecutive renders?', tags: ['useCallback'] },
  { q: 'Across renders (deps empty), what is fn?\n\n```jsx\nconst fn = useCallback(() => {}, []);\n```', opts: ['a new function on every render', 'the same function reference on every render', 'the function\'s return value, not the function', 'a new function whenever any state changes'], a: 1, e: 'With an empty dependency list there is nothing that can differ between renders, so React keeps returning the function created on the first render and fn stays referentially equal - confirmed across three renders. That is the point: a stable prop lets a memo child skip re-rendering and stops effects from re-running. The cost is that the closure is frozen on the first render\'s values, which is where stale-closure bugs come from.', intro: 'An empty list holds nothing that can change. Ask what that means for the comparison React makes on each render.', tags: ['useCallback'] },
  { q: 'What is the bug if count changes?\n\n```jsx\nuseCallback(() => console.log(count), []);\n```', opts: ['it always logs the latest count, because closures read live values', 'it logs the count from the render where the callback was created', 'it logs undefined, because count is not in the dependency list', 'it re-creates the callback on each render, so the memo does nothing'], a: 1, e: 'An empty dependency list makes React keep handing back the function built on the first render, and that function closed over that render\'s count - so it logs the old number however often the component re-renders. Measured: rendered count 5, callback logged 0. count is captured, not missing, so nothing is undefined; the fixes are to list count in the dependencies or to avoid reading it at all, for example with a functional update.', intro: 'Look at the dependency list, then ask when React would ever build this function a second time.', tags: ['useCallback', 'Gotchas'] },
  { q: 'useCallback(fn, deps) is roughly equivalent to:', opts: ['useMemo(() => fn, deps)', 'useEffect(fn, deps)', 'useRef(fn)', 'useState(fn)'], a: 0, e: 'useMemo caches whatever its calculation returns, so a calculation that returns a function caches a function - which is useCallback. react.dev gives the same simplified implementation: function useCallback(fn, dependencies) { return useMemo(() => fn, dependencies); }. Watch the extra arrow: useMemo(fn, deps) would call fn and cache its result instead. The other options are different jobs entirely - useEffect runs after the commit, useRef holds a mutable box, and useState(fn) would treat the function as a lazy initializer.', intro: 'One of these hooks already caches values between renders. Ask what you would have to hand it so that the cached value is a function.', tags: ['useCallback'] },

  // ── Level 19 — useReducer ──────────────────────────────────────────────
  { q: 'The button is clicked once. What does it show?\n\n```jsx\nfunction reducer(state, action) {\n  switch (action.type) {\n    case "inc":\n      return state + 1;\n    default:\n      return state;\n  }\n}\n\nfunction Counter() {\n  const [count, dispatch] = useReducer(reducer, 0);\n  return <button onClick={() => dispatch({ type: "inc" })}>{count}</button>;\n}\n```', opts: ['0', '1', '2', 'undefined'], a: 1, e: 'useReducer starts at the initial value 0, and each dispatch hands the current state and the action to the reducer; the \'inc\' case returns state + 1, so after one click the state is 1 and the button re-renders with it. 2 would need two clicks, and 0 is what an unrecognized action gives you, because the default branch returns the state untouched - which is exactly why that branch exists. Measured: 0 at mount, 1 after dispatch({ type: \'inc\' }), still 1 after an unknown action.', intro: 'The reducer computes the next state from the current one. Apply the branch that matches this action to the initial value.', tags: ['useReducer'] },
  { q: 'What does dispatch do?\n\n```jsx\nconst [state, dispatch] = useReducer(reducer, { n: 0 });\n```', opts: ['reads the current state and returns it', 'sends an action to the reducer, which returns the next state', 'replaces the state with the object you pass to it', 'calls the reducer at once and returns its result'], a: 1, e: 'dispatch only describes what happened: it queues the action, then React calls reducer(state, action) to compute the next state and re-renders with it. That is the difference from a setState call - the object you dispatch is not written into state, the reducer decides what state becomes. dispatch also returns undefined rather than the new state, so you always read the value from the state variable on the next render.', intro: 'Beginners read dispatch as a setter with extra steps. Compare what you hand to each, and what each one does with it.', tags: ['useReducer'] },
  { q: 'The button is clicked once. What does it show?\n\n```jsx\nfunction reducer(s, a) {\n  if (a.type === "add") return s + a.value;\n  return s;\n}\n\nfunction Total() {\n  const [n, dispatch] = useReducer(reducer, 10);\n  return <button onClick={() => dispatch({ type: "add", value: 5 })}>{n}</button>;\n}\n```', opts: ['10', '15', '5', 'undefined'], a: 1, e: 'An action is just an object, so it can carry data alongside its type: the reducer reads a.value and returns s + a.value, which is 10 + 5 = 15 after one click. 5 is the payload on its own and 10 is what an action the reducer does not match would leave you with, since it returns the state unchanged. Measured: n was 10 at mount and 15 after dispatch({ type: \'add\', value: 5 }).', intro: 'The action carries more than a type. Ask what the reducer does with the rest of it.', tags: ['useReducer'] },
  { q: 'useReducer is preferable to useState when:', opts: ['state is a single boolean toggled in one place', 'several related values change together through named actions', 'you want state updates that do not cause a re-render', 'state has to be shared by components in different subtrees'], a: 1, e: 'useReducer pays off when several related values move together and the transitions have names: the rules live in one pure function you can read and unit-test, and components only say what happened. A single boolean is plainer with useState. Updates that must not re-render belong in a ref, and sharing state with distant components is context\'s job - a reducer is often combined with context, but it does not do that by itself.', intro: 'Both hooks store state and both re-render. Ask which one gives the update rules a single home.', tags: ['useReducer'] },

  // ── Level 20 — useContext ──────────────────────────────────────────────
  { q: 'What does theme hold when no Provider for ThemeContext is above this component?\n\n```jsx\nconst ThemeContext = createContext("light");\n\nfunction Panel() {\n  const theme = useContext(ThemeContext);\n  return <p>{theme}</p>;\n}\n```', opts: ['undefined', '"light"', 'null', 'an error'], a: 1, e: 'With no matching Provider above Panel, useContext returns the default passed to createContext, so theme is "light". undefined is what you would get only if createContext had been called with no argument at all, and React does not throw: a forgotten Provider fails silently and the app quietly runs on defaults. That is why teams often pass null as the default and read the context through a small hook that throws when it is null.', intro: 'createContext was called with an argument. Ask what that argument is for, given that nothing in the tree has supplied a value.', tags: ['useContext'] },
  { q: 'What does Child render?\n\n```jsx\nconst ThemeContext = createContext("light");\n\nfunction Child() {\n  return <p>{useContext(ThemeContext)}</p>;\n}\n\n<ThemeContext.Provider value="dark">\n  <ThemeContext.Provider value="high-contrast">\n    <Child />\n  </ThemeContext.Provider>\n</ThemeContext.Provider>\n```', opts: ['"light"', '"dark"', '"high-contrast"', 'undefined'], a: 2, e: 'React walks up from Child to the first matching Provider and stops there, so the inner value "high-contrast" is what it reads. "dark" would be right only if React kept going to the outermost Provider, and "light", the createContext default, applies only when there is no Provider above at all. Nesting is how one section overrides a page-wide value.', intro: 'Two Providers wrap this component and each supplies a value. Decide where React stops when it walks up the tree from Child.', tags: ['useContext'] },
  { q: 'What problem does Context solve?', opts: ['Prop drilling through many layers', 'Re-rendering less when shared data changes', 'Keeping state alive after a component unmounts', 'Storing data outside React so any module can read it'], a: 0, e: 'Context removes the chore of threading a prop through components that never use it: the value goes in at a Provider and any descendant reads it directly. It is not a render optimization, since every consumer re-renders when the Provider\'s value changes, even one wrapped in memo. The value still lives in ordinary state somewhere, so it disappears when that owner unmounts.', intro: 'Context is not free: every consumer re-renders when the Provider\'s value changes, memo or not. Ask what it was designed to remove instead.', tags: ['useContext'] },
  { q: 'What is rendered (no Provider)?\n\n```jsx\nconst Ctx = createContext(0);\nfunction A() {\n  const v = useContext(Ctx);\n  return <p>{v}</p>;\n}\n```', opts: ['0', 'undefined', 'null', 'an error'], a: 0, e: 'With no Provider, the default value 0 is used.', tags: ['useContext'] },

  // ── Level 21 — Custom Hooks ────────────────────────────────────────────
  { q: 'What makes this a custom hook?\n\n```jsx\nfunction useCounter(start) {\n  const [n, setN] = useState(start);\n  return { n, inc: () => setN(p => p + 1) };\n}\n```', opts: ['Its name starts with "use" and it calls hooks', 'It returns an array, the way useState does', 'It is called from inside a component', 'It is exported from its own module'], a: 0, e: 'useCounter qualifies on two counts: it calls useState, which only components and other hooks may do, and its name starts with "use", which is the signal React\'s lint rules key on to enforce that. Being called from a component is not enough on its own, since plain helper functions are called from components all the time, and the return shape is free: an object works as well as an array. Where the function lives does not matter either, so a custom hook can sit in the same file as the component that uses it.', intro: 'An ordinary helper can also take an argument and return an object. Ask what this one does that a plain helper is not allowed to do.', tags: ['Custom hooks'] },
  { q: 'The button is clicked once. What does it show?\n\n```jsx\nfunction useToggle(init) {\n  const [on, setOn] = useState(init);\n  return [on, () => setOn(p => !p)];\n}\n\nfunction Panel() {\n  const [open, toggle] = useToggle(false);\n  return <button onClick={toggle}>{String(open)}</button>;\n}\n```', opts: ['false', 'true', 'undefined', 'the button text never changes'], a: 1, e: 'toggle calls setOn(p => !p), so the stored value flips from false to true and React re-renders Panel; on that render useToggle hands back the new value and the button shows true. The open binding created during the first render stays false forever, which is exactly why you read state from the fresh hook call rather than from a variable captured earlier.', intro: 'The click runs the updater p => !p. Ask which render\'s value the button prints.', tags: ['Custom hooks'] },
  { q: 'Two components using the same custom hook share:', opts: ['The same state', 'Independent state', 'Only refs', 'Props'], a: 1, e: 'Each call to a hook gets its own isolated state; hooks share logic, not state.', tags: ['Custom hooks'] },
  { q: 'What does useDouble(8) return?\n\n```jsx\nfunction useDouble(n) {\n  return n * 2;\n}\nuseDouble(8);\n```', opts: ['8', '16', 'undefined', 'a hook'], a: 1, e: 'It simply returns n * 2 = 16.', tags: ['Custom hooks'] },

  // ── Level 22 — Keys & Reconciliation ───────────────────────────────────
  { q: 'Why does React need keys in lists?', opts: ['To match each item to the same component across renders', 'To decide the order the items appear in', 'To give each row a unique CSS hook', 'To tell React how many items to render'], a: 0, e: 'Each render hands React a fresh array of elements, and it has to decide which of them correspond to what is already on screen. The key is that identity: matching keys mean the same item, so React updates it in place and keeps its state and DOM node, while an unmatched key means an insert or a delete. Order comes from the array itself, not from the keys, and the key is never written to the DOM as an attribute.', intro: 'Nothing about the key reaches the DOM. Ask what React does with it while comparing this render against the last one.', tags: ['Keys', 'Reconciliation'] },
  { q: 'Why is using the array index as a key risky?\n\n```jsx\n{items.map((item, i) => <Row key={i} {...item} />)}\n```', opts: ['Inserting or reordering leaves state on the wrong row', 'React warns about numeric keys and ignores them', 'Index keys make each update slower than string keys', 'The problem only appears in lists longer than the viewport'], a: 0, e: 'React matches rows by key, so with key={i} the first row is key 0 whatever item sits there. Delete or insert at the front and the items shift while the keys do not, so React reuses the existing row component, and its state, for a different item: a checked box or a focused input ends up on the wrong row. Index keys are safe only when the list never reorders and items are only ever added or removed at the end.', intro: 'Delete the first item and re-render. Every remaining row now carries a key that used to belong to a different item.', tags: ['Keys', 'Gotchas'] },
  { q: 'Changing a component’s key causes React to:', opts: ['Unmount the old instance and mount a fresh one', 'Keep the instance and update its props', 'Keep the state but rebuild the DOM node', 'Warn in development and reuse the instance'], a: 0, e: 'React identifies an element by its position and its key, so a new key means a different element: the old one unmounts, its state and effect cleanups run, and a new instance mounts with fresh state. Updating in place is what happens when the key stays the same and only props change. This is also a deliberate technique: put key={userId} on a profile form and switching users resets the form for free.', intro: 'React treats key as identity, not as a prop. Ask what has to happen to an element whose identity just changed.', tags: ['Keys', 'Reconciliation'] },
  { q: 'What makes a good key for a list item?', opts: ['Stable across renders and unique among siblings', 'Freshly generated on each render, so it is unique', 'The item\'s position in the array', 'One value shared by every item in the list'], a: 0, e: 'A key has to let React recognize the same item on the next render, which rules out a value regenerated every render, and it has to tell siblings apart, which rules out one shared value. The item\'s own id is the usual answer. Position works only when items never move, because an insert at the front changes every position while the items themselves are unchanged.', intro: 'Run the list twice with nothing changed. Which of these keys would come out different the second time?', tags: ['Keys'] },

  // ── Level 23 — Performance Patterns ────────────────────────────────────
  { q: 'When does React.memo let a component skip re-rendering?', opts: ['Its parent re-renders and its props are shallow-equal', 'Its own state changes but its props do not', 'A context it reads changes but its props do not', 'A prop is a new object with the same contents'], a: 0, e: 'memo keeps the previous props and compares them value by value with Object.is, so when the parent re-renders and every prop is the same value React reuses the previous output. It does nothing about renders that start inside the component: its own state update, and a change in a context it reads, re-render it either way. A prop that is a new object with the same contents counts as changed, because the comparison is shallow, and even with equal props React may still re-render: memo is an optimization, not a guarantee.', intro: 'memo watches one thing only, and it is not what happens inside the component. Ask where the re-render starts in each case.', tags: ['Performance', 'memo'] },
  { q: 'Inner is wrapped in memo but re-renders whenever the parent does. Why?\n\n```jsx\nconst Child = React.memo(Inner);\n\nfunction Parent() {\n  const [n, setN] = useState(0);\n  return <Child onClick={() => {}} />;\n}\n```', opts: ['The arrow passed to onClick is a new function each render', 'memo compares props deeply, so functions never match', 'memo only works on components that take no props', 'A parent\'s state change always re-renders its children'], a: 0, e: 'memo compares each new prop with the old one using Object.is. `() => {}` builds a new function object on every render of Parent, so onClick is never the same value twice, the comparison always fails, and you pay for the comparison on top of the render. Wrapping the handler in useCallback with the right dependencies makes the prop stable and lets memo do its job; a parent\'s re-render on its own does not force a memoized child to re-render.', intro: 'The prop is written inline in the parent\'s JSX. Ask what value it holds on the second render compared with the first.', tags: ['Performance', 'memo'] },
  { q: 'What do useMemo and useCallback give you?', opts: ['The same value across renders until a dependency changes', 'A guarantee that the component never re-renders', 'A cached result that survives a page reload', 'State that updates without triggering a render'], a: 0, e: 'Both cache across renders: useMemo keeps the result of a calculation, useCallback keeps the function object itself, and both recompute when a dependency changes. That buys two things, skipping an expensive recalculation and keeping a prop or an effect dependency referentially stable so a memoized child or an effect does not fire needlessly. Neither stops the component itself from re-rendering, and the cache lives in the mounted component, so a reload starts from nothing.', intro: 'Neither hook stops the component from rendering, and nothing they store outlives the page. Ask what is left for them to hold on to.', tags: ['Performance'] },
  { q: 'What does wrapping everything in memo, useMemo and useCallback cost?', opts: ['Comparisons and dependency arrays that often save nothing', 'Nothing measurable, so it is free insurance', 'Re-renders stop entirely for those components', 'The build fails once too many hooks are used'], a: 0, e: 'Each memo boundary stores the previous props and compares them on every parent render, and each useMemo or useCallback stores a value alongside its dependency array. When the values change anyway, or the component was cheap to render, that bookkeeping and the extra code buy nothing, and a dependency list that drifts out of date becomes a new class of bug. Profile first, then memoize the components that actually show up as expensive.', intro: 'Ask what React has to do on every render just to find out whether it can skip one. Then ask who keeps every dependency array correct.', tags: ['Performance'] },

  // ── Level 24 — Common Pitfalls ─────────────────────────────────────────
  { q: 'What happens?\n\n```jsx\nfunction App() {\n  const [n, setN] = useState(0);\n  setN(n + 1);\n  return <p>{n}</p>;\n}\n```', opts: ['React stops it with a "Too many re-renders" error', 'It renders once and shows 1', 'It renders once and shows 0', 'It re-renders forever until the tab freezes'], a: 0, e: 'Calling setN during render schedules another render of the same component, and that render calls setN again with a larger value, so it never settles. React notices the runaway and throws "Too many re-renders. React limits the number of renders to prevent an infinite loop." rather than locking up the tab. A value derived from state or props should be computed during render, not written back into state, and an update that reacts to something belongs in an event handler.', intro: 'The setter runs during the render itself, and it asks for a different value every time. Ask what the next render then does.', tags: ['Pitfalls'] },
  { q: 'What is the problem?\n\n```jsx\nif (loading) {\n  const [x, setX] = useState(0);\n}\n```', opts: ['useState runs only on some renders, so the hook order changes', 'useState must be the first statement in the component', 'The state resets to 0 every time loading changes', 'State has to be declared with let rather than const'], a: 0, e: 'React does not know hooks by name; it matches each call to its stored state by the order the calls happen. Behind an if, this useState disappears on renders where loading is false, so every hook after it lines up with the wrong slot and React aborts with "Rendered fewer hooks than expected." Call hooks unconditionally at the top level and put the condition inside the value you compute or inside the effect body.', intro: 'Run this component twice, once with loading true and once with loading false. Ask how many hooks React sees each time.', tags: ['Pitfalls', 'Rules of hooks'] },
  { q: 'The button is clicked once. What do the two logs show?\n\n```jsx\nfunction Counter() {\n  const [n, setN] = useState(0);\n\n  function handleClick() {\n    console.log(n);\n    setN(5);\n    console.log(n);\n  }\n\n  return <button onClick={handleClick}>{n}</button>;\n}\n```', opts: ['0 then 0', '0 then 5', '5 then 5', 'undefined then 5'], a: 0, e: 'n is a plain constant belonging to the render that is currently running, so setN(5) cannot change it: it asks React to render again with a new value. Both logs read the same snapshot and print 0, and the button shows 5 only on the next render. This is why you use setN(p => p + 1) when the next value depends on the current one, rather than reading n twice in a row.', intro: 'n is a const created when this render ran. Ask whether calling the setter can change a value that already exists.', tags: ['Pitfalls', 'useState'] },
  { q: 'What is the issue?\n\n```jsx\nuseEffect(async () => {\n  await fetchData();\n}, []);\n```', opts: ['An async callback returns a promise, not a cleanup function', 'await is not allowed anywhere inside a component tree', 'An empty dependency array stops the effect from running at all', 'fetchData has to be wrapped in useCallback first'], a: 0, e: 'React keeps the effect\'s return value and calls it as the cleanup when the component unmounts or the effect re-runs. An async function always returns a promise, so there is nothing valid to call, and React warns: "useEffect must not return anything besides a function, which is used for clean-up." Declare an async function inside the effect and call it, then use a real cleanup to ignore a response that arrives after unmount.', intro: 'The callback is marked async, so it returns a value even though the body has no return statement. Ask whether React can use that value.', tags: ['Pitfalls', 'useEffect'] },

  // ── Level 25 — Mixed Mastery ───────────────────────────────────────────
  { q: 'What does this component do?\n\n```jsx\nfunction App() {\n  const [n, setN] = useState(0);\n  useEffect(() => {\n    const id = setInterval(() => setN(p => p + 1), 1000);\n    return () => clearInterval(id);\n  }, []);\n  return <p>{n}</p>;\n}\n```', opts: ['Increments n once a second and clears the interval on unmount', 'Increments n once a second but leaves the interval running on unmount', 'Increments n once, because the dependency array is empty', 'Stops at 1, because the interval captured n = 0'], a: 0, e: 'The effect runs once after mount, starts the interval and returns a cleanup, so the timer is cleared when App unmounts and on Strict Mode\'s development remount. Writing the update as p => p + 1 means the callback never needs the n captured when the effect ran, so the counter keeps climbing; setN(n + 1) with an empty dependency array would stick at 1. The empty array is also what keeps one interval instead of restarting a new one on every render.', intro: 'Two details decide this: the empty dependency array and the p => p + 1 form of the update. Work out what each one prevents.', tags: ['Mastery'] },
  { q: 'How many times does this component fetch in a production build?\n\n```jsx\nfunction List() {\n  const [items, setItems] = useState([]);\n\n  useEffect(() => {\n    fetch("/api").then(r => r.json()).then(setItems);\n  }, []);\n\n  return <ul>{items.map(i => <li key={i.id}>{i.name}</li>)}</ul>;\n}\n```', opts: ['Once after mount, then never again', 'After every render, because setItems causes one', 'Only when items changes', 'Never, until something reads items'], a: 0, e: 'An empty dependency array tells React there is nothing to watch, so the body runs after the first render and never again: one request goes out and setItems puts the JSON into state. Drop the array and every state update would re-run the effect, so the fetch would fire again after every render. Two caveats belong with this pattern: in development Strict Mode mounts the component twice, so you will see two requests, and with no cleanup a response that arrives after unmount or after a newer request still lands in state.', intro: 'Look at the second argument to useEffect and decide what it tells React about running the body again.', tags: ['Mastery'] },
  { q: 'When does doubled recompute?\n\n```jsx\nconst doubled = useMemo(() => items.map(x => x * 2), [items]);\n```', opts: ['Every render', 'Only when items changes', 'Never', 'On unmount'], a: 1, e: 'useMemo recomputes the mapped array only when items changes.', tags: ['Mastery'] },
  { q: 'What does clicking the button do?\n\n```jsx\nfunction Toggle() {\n  const [on, setOn] = useState(false);\n  return <button onClick={() => setOn(o => !o)}>{on ? "ON" : "OFF"}</button>;\n}\n```', opts: ['Flips the label between ON and OFF on every click', 'Shows ON after the first click and stays there', 'Flips the label only when the parent re-renders', 'Shows OFF forever, because on is false in the handler'], a: 0, e: 'Each click calls setOn(o => !o); React passes the latest stored value in as o and stores its negation, so the state alternates and the label follows it. setOn(!on) would also work here, but it reads the snapshot from the render that created the handler, which breaks as soon as two updates queue in one event. Nothing in the component depends on its parent, so the parent never enters into it.', intro: 'The updater is handed the current value rather than reading on from this render. Follow what it returns on the second click.', tags: ['Mastery'] },
];
